// ====== ACCESS SETTINGS (edit here) ======
const ACCESS_PIN = "";   // e.g. "4821" — empty = no access code required (set one for public use!)
const DAILY_LIMIT = 30;  // max generations per day. 0 = unlimited (only for trusted/internal use)
// =========================================

const item = items[0];
const body = item.json.body || item.json;
const { pin, website, ...payload } = body;

// Unguessable job id: no timestamp prefix -> not enumerable. Uses Web Crypto
// when the sandbox exposes it, else a long Math.random token (n8n task-runner
// blocks crypto). For true CSPRNG ids, set NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const jobId = (typeof crypto !== "undefined" && crypto.randomUUID) ? crypto.randomUUID().replace(/-/g, "") : Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join("");

const base = { ...payload, jobId, _pinOk: false, _limit: DAILY_LIMIT };

// Bot honeypot — checked server-side (a direct POST bypasses the browser check)
if ((website || "").trim()) {
  // "bot" et non "pin_required" : sinon le front ouvre la modale de PIN et EFFACE
  // le code memorise d'un utilisateur legitime (autofill du navigateur).
  return [{ json: { ...base, denyReason: "bot" }, binary: item.binary }];
}

// Upload validation — a direct POST could skip the client-side checks
const photo = item.binary && item.binary.photo;
const mimeOk = photo && String(photo.mimeType || "").indexOf("image/") === 0;
// n8n expose fileSize comme une CHAINE formatee ("2.1 MB"), jamais un nombre :
// l'ancien test `typeof fileSize !== "number"` etait donc toujours vrai -> garde-fou mort.
const parseSize = (fs) => {
  if (typeof fs === "number") return fs;
  const m = String(fs || "").trim().match(/^([\d.]+)\s*(B|kB|KB|MB|GB)$/i);
  if (!m) return null; // format inconnu -> on ne bloque pas
  const mult = { b: 1, kb: 1024, mb: 1024 * 1024, gb: 1024 * 1024 * 1024 };
  return parseFloat(m[1]) * mult[m[2].toLowerCase()];
};
const photoBytes = photo ? parseSize(photo.fileSize) : null;
const sizeOk = !photo || photoBytes === null || photoBytes <= 16 * 1024 * 1024;
if (!mimeOk || !sizeOk) {
  return [{ json: { ...base, denyReason: "bad_file" }, binary: item.binary }];
}

// Access code
const pinOk = !ACCESS_PIN || (pin || "") === ACCESS_PIN;
const denyReason = pinOk ? "" : (pin ? "pin_invalid" : "pin_required");
return [{ json: { ...payload, jobId, _pinOk: pinOk, _limit: DAILY_LIMIT, denyReason }, binary: item.binary }];

const g = $('Access gate').first();
// Daily limit: the node default (DAILY_LIMIT in Access gate) is overridden by
// the value saved from the Usage & costs dashboard, if any.
const sd = $getWorkflowStaticData('global');
const override = (sd && sd.dailyLimit !== undefined && sd.dailyLimit !== null && sd.dailyLimit !== '') ? Number(sd.dailyLimit) : null;
const limit = (override !== null && !isNaN(override)) ? override : (g.json._limit || 0);
const used = items.filter(i => i.json && i.json.jobId).length;
const ok = !limit || used < limit;
return [{ json: { ...g.json, _quotaOk: ok, _limit: limit, denyReason: ok ? "" : "quota" }, binary: g.binary }];

// =========================================================================
// 1. ACTION DETECTION
// Reads the explicit `action` field (the form always sends it). Never scans
// free text (comment) or generated values (jobId) — a comment like
// "clean modern look" must NOT turn a staging into a cleaning job.
const actionSource = String(
    items[0].json.action ||
    items[0].json['What do you want to do?'] ||
    items[0].json['Que voulez-vous faire ?'] ||
    ""
).toUpperCase();

let chosenAction = "FURNISH";
let actionEN = "FURNISH";

if (actionSource.includes("EMPTY") || actionSource.includes("VIDER") || actionSource.includes("LEEREN")) {
    chosenAction = "EMPTY";
    actionEN = "EMPTY";
} else if (actionSource.includes("CLEAN") || actionSource.includes("NETTOYER") || actionSource.includes("AUFRÄUM")) {
    chosenAction = "CLEAN";
    actionEN = "CLEAN";
} else if (actionSource.includes("UPSCALE") || actionSource.includes("4K") || actionSource.includes("HD") || actionSource.includes("HOCHSKALIER")) {
    chosenAction = "UPSCALE";
    actionEN = "UPSCALE";
}

// =========================================================================
// 2. STYLE DETECTION (normalized to simple English names)
const rawStyle = (items[0].json.style || items[0].json['Which style / brand do you want?'] || items[0].json['Quel style / marque souhaitez-vous ?'] || "MODERN").toUpperCase();
let chosenStyle = rawStyle.replace(/\s*\(.*?\)/g, '').trim();

if (chosenStyle.includes("SIGNATURE")) chosenStyle = "SIGNATURE STYLE";
if (chosenStyle.includes("ART DECO") || chosenStyle.includes("ART DÉCO")) chosenStyle = "ART DECO";
if (chosenStyle === "MODERNE" || chosenStyle === "MODERN") chosenStyle = "MODERN";
if (chosenStyle.includes("LUXURY MODERN") || chosenStyle.includes("MODERNE LUXE")) chosenStyle = "LUXURY MODERN";
if (chosenStyle.includes("ULTRA LUXE") || chosenStyle.includes("ULTRA LUXURY")) chosenStyle = "ULTRA LUXURY";
if (chosenStyle.includes("SCANDINAV")) chosenStyle = "SCANDINAVIAN";
if (chosenStyle.includes("INDUSTRI")) chosenStyle = "INDUSTRIAL";
if (chosenStyle.includes("ECLECTIC") || chosenStyle.includes("ÉCLECTIQUE")) chosenStyle = "ECLECTIC CHIC";
if (chosenStyle === "JAPANDI") chosenStyle = "JAPANDI";
if (/\bNATURE\b/.test(chosenStyle) || chosenStyle.includes("BIOPHILI")) chosenStyle = "NATURE INSPIRED";
if (chosenStyle.includes("BOHO") || chosenStyle.includes("BOHÈME")) chosenStyle = "BOHO CHIC";
if (chosenStyle.includes("COASTAL") || chosenStyle.includes("MEDITERRAN")) chosenStyle = "COASTAL";
if (chosenStyle.includes("PARISIAN") || chosenStyle.includes("HAUSSMANN")) chosenStyle = "PARISIAN CHIC";
if (chosenStyle.includes("MID-CENTURY")) chosenStyle = "MID-CENTURY";
if (chosenStyle.includes("LIGNE ROSET")) chosenStyle = "LIGNE ROSET";
if (chosenStyle.includes("AMERICAN LUXURY") || chosenStyle.includes("RESTORATION") || chosenStyle === "RH") chosenStyle = "AMERICAN LUXURY";
if (chosenStyle.includes("HOTEL") || chosenStyle.includes("LOUNGE")) chosenStyle = "HOTEL LOUNGE";
if (chosenStyle.includes("CALIFORNIA")) chosenStyle = "CALIFORNIA MODERN";
if (chosenStyle.includes("PORCELANOSA")) chosenStyle = "PORCELANOSA";
if (chosenStyle === "POLIFORM") chosenStyle = "POLIFORM";

// =========================================================================
// 3. ROOM DETECTION
// Reads the explicit `room` field (the form always sends it). The fallback
// scan (for direct API calls) only looks at user-named fields — never the
// comment, the style, the jobId or internal keys, so free text and random
// ids can never hijack the detected room.
const roomSource = String(
    items[0].json.room ||
    items[0].json['What is this room?'] ||
    items[0].json['Quelle est cette pièce ?'] ||
    ""
).toUpperCase();

let roomScan = roomSource;
if (!roomScan) {
    const EXCLUDED_KEYS = ["style", "comment", "jobId", "pin", "website", "denyReason",
        "Which style / brand do you want?", "Quel style / marque souhaitez-vous ?"];
    roomScan = Object.keys(items[0].json)
        .filter(k => EXCLUDED_KEYS.indexOf(k) === -1 && k.charAt(0) !== "_")
        .map(k => String(items[0].json[k]).toUpperCase())
        .join(" ");
}

let roomEN = "LIVING ROOM";

if (roomScan.includes("GRAND SALON") || roomScan.includes("LARGE LIVING ROOM") || roomScan.includes("GROSSES WOHNZIMMER")) {
    roomEN = "LARGE LIVING ROOM";
} else if (roomScan.includes("STUDIO")) {
    roomEN = "STUDIO APARTMENT";
} else if (roomScan.includes("KITCHEN") || roomScan.includes("CUISINE") || roomScan.includes("KÜCHE")) {
    roomEN = "KITCHEN";
} else if (roomScan.includes("KIDS") || roomScan.includes("ENFANT") || roomScan.includes("KINDERZIMMER")) {
    roomEN = "KIDS ROOM";
} else if (roomScan.includes("BEDROOM") || roomScan.includes("CHAMBRE") || roomScan.includes("SCHLAFZIMMER")) {
    roomEN = "BEDROOM";
} else if (roomScan.includes("BALCONY") || roomScan.includes("BALCON") || roomScan.includes("BALKON")) {
    roomEN = "BALCONY";
} else if (roomScan.includes("OFFICE") || roomScan.includes("BUREAU") || roomScan.includes("BÜRO")) {
    roomEN = "OFFICE";
} else if (roomScan.includes("BATH") || roomScan.includes("BAIN") || roomScan.includes("BAD")) {
    roomEN = "BATHROOM";
}

// =========================================================================
// 4. BRAND-SAFETY SHIELD (keeps kitchen brands in kitchens, etc.)
const kitchenBrands = ["BULTHAUP", "BOFFI", "ARTHUR BONNET"];
const livingBrands = ["VITRA", "BOCONCEPT", "ROCHE BOBOIS", "MINOTTI", "KNOLL", "HERMAN MILLER", "LIGNE ROSET", "AMERICAN LUXURY"];

// Rule 1: block pure kitchen brands outside the kitchen
if (roomEN !== "KITCHEN" && kitchenBrands.includes(chosenStyle)) {
    chosenStyle = "LUXURY MODERN";
}
// Rule 2: block living-room furniture brands inside the kitchen
if (roomEN === "KITCHEN" && livingBrands.includes(chosenStyle)) {
    chosenStyle = "ULTRA LUXURY";
}
// Rule 3: Poliform allowed ONLY in Kitchen and Bedroom
if (chosenStyle === "POLIFORM" && roomEN !== "KITCHEN" && roomEN !== "BEDROOM") {
    chosenStyle = "LUXURY MODERN";
}
// Rule 4: Porcelanosa allowed ONLY in Bathroom
if (chosenStyle === "PORCELANOSA" && roomEN !== "BATHROOM") {
    chosenStyle = "ULTRA LUXURY";
}
// Rule 5: enforce the full catalog room restrictions server-side too.
// The form already filters styles per room — this guards direct API calls.
// ROOM_RULES is injected at build time from the same catalog the form uses,
// so the two can never drift apart.
const ROOM_RULES = {"SIGNATURE STYLE":["*"],"MODERN":["*"],"LUXURY MODERN":["*"],"ULTRA LUXURY":["LIVING ROOM","BEDROOM","BATHROOM"],"SCANDINAVIAN":["LIVING ROOM","BEDROOM","KIDS ROOM","STUDIO"],"INDUSTRIAL":["LIVING ROOM","KITCHEN","OFFICE","STUDIO"],"MID-CENTURY":["LIVING ROOM","OFFICE","STUDIO"],"ART DECO":["LIVING ROOM","BEDROOM"],"PARISIAN CHIC":["LIVING ROOM","BEDROOM"],"WABI-SABI":["LIVING ROOM","BEDROOM","STUDIO"],"ECLECTIC CHIC":["LIVING ROOM"],"JAPANDI":["LIVING ROOM","BEDROOM","STUDIO"],"NATURE INSPIRED":["LIVING ROOM","BATHROOM","BALCONY"],"BOHO CHIC":["LIVING ROOM","BEDROOM","BALCONY","STUDIO"],"COASTAL":["LIVING ROOM","BEDROOM","BALCONY","STUDIO"],"HOTEL LOUNGE":["LARGE LIVING ROOM"],"CALIFORNIA MODERN":["LARGE LIVING ROOM"],"AMERICAN LUXURY":["LARGE LIVING ROOM"],"VITRA":["LIVING ROOM","OFFICE"],"BOCONCEPT":["LIVING ROOM","BEDROOM","STUDIO"],"ROCHE BOBOIS":["LIVING ROOM","BEDROOM"],"MINOTTI":["LIVING ROOM"],"KNOLL":["LIVING ROOM","OFFICE"],"HERMAN MILLER":["OFFICE"],"LIGNE ROSET":["LIVING ROOM"],"ARTHUR BONNET":["KITCHEN"],"BULTHAUP":["KITCHEN"],"BOFFI":["KITCHEN"],"POLIFORM":["KITCHEN","BEDROOM"],"PORCELANOSA":["BATHROOM"]};
const allowedRooms = ROOM_RULES[chosenStyle];
if (allowedRooms && allowedRooms.indexOf("*") === -1) {
    const roomAllowed =
        allowedRooms.indexOf(roomEN) !== -1 ||
        (roomEN === "LARGE LIVING ROOM" && allowedRooms.indexOf("LIVING ROOM") !== -1) ||
        (roomEN === "STUDIO APARTMENT" && allowedRooms.indexOf("STUDIO") !== -1);
    if (!roomAllowed) chosenStyle = "LUXURY MODERN";
}

// =========================================================================
// 5. STYLE LIBRARY
// ⭐ "SIGNATURE STYLE" is YOUR slot: describe your agency's look (palette,
//    furniture language, lighting, art, mood, strict negatives). The more
//    specific you are, the more consistent the results. Edit the text below.
const styleLibrary = {
    "SIGNATURE STYLE": "Bright airy interiors with white walls and warm light oak floors, sculptural contemporary furniture, ONE bold color accent varied each generation (teal, mustard, dusty pink, emerald), one statement pendant lamp, one large abstract artwork, one or two plants in minimal pots. MOOD: joyful, curated, like a boutique design gallery. STRICT NEGATIVE: no rustic farmhouse, no clutter, no brown leather.",
    "MODERN": "smooth textures, neutral colors, glass and metal, bright atmosphere.",
    "LUXURY MODERN": "noble materials, sleek finishes, brass touches, contemporary design furniture.",
    "ULTRA LUXURY": "omnipresent marble, precious metals, velvet, exotic wood, dramatic lighting.",
    "SCANDINAVIAN": "light wood dominant, matte pastels, cozy textiles, hygge vibe.",
    "INDUSTRIAL": "brick/concrete look, raw wood, earthy tones.",
    "WABI-SABI": "elegant raw minimalism, textured walls, aged wood, linen textiles.",
    "MID-CENTURY": "1950s/60s design, warm walnut wood, splayed-leg furniture.",
    "PARISIAN CHIC": "elegant contrast, bright classical architecture paired with ultra-contemporary design furniture.",
    "ART DECO": "Gatsby atmosphere, geometric patterns, deep velvet, brass/gold touches, marble.",
    "ECLECTIC CHIC": "Bold Color-blocked Minimalism with Curated Statement Design Icons. The space is a quirky, airy gallery. FURNISHING: Use only a specific curated set of icons: ONE round white Saarinen Tulip dining table with a pair of white Tulip-style chairs featuring vibrant color-blocking (e.g., yellow and red cushions), ONE iconic Mid-Century modern lounge chair (e.g., leather swivel chair), ONE large color-blocked statement sofa, ONE giant Arco polished chrome floor lamp. DECORATION: ONE large abstract art canvas. LARGE scale contemporary art sculptures. ABSOLUTELY NO other furniture or traditional small clutter. LARGE floor space clear. Airy modern gallery feel.",

    "JAPANDI": "fusion of Japanese minimalism and Scandinavian functionality. Low-profile furniture, natural light wood, muted earthy tones, zen and uncluttered atmosphere.",
    "NATURE INSPIRED": "nature-inspired interior, abundant lush indoor plants, organic shapes, natural materials like stone and wood, earthy greens and warm browns, lots of natural light.",
    "BOHO CHIC": "relaxed and warm atmosphere, rattan and wicker furniture, textured vintage rugs, macrame details, earthy warm tones, cozy plants.",
    "COASTAL": "sun-drenched luxury, white lime-washed walls, terracotta touches, olive green accents, light linen textiles, airy and relaxed coastal vibe.",

    "AMERICAN LUXURY": "american oversized luxury, monochromatic neutral palettes, massive deep-seated sectional sofas, monumental reclaimed wood coffee tables, oversized floor and table lamps, grand and structured elegance designed to fill a large space.",
    "HOTEL LOUNGE": "high-end hotel lobby aesthetic, symmetrical layout, multiple distinct seating areas to perfectly fill the large open space, elegant facing sofas, oversized area rugs to define zones, dramatic statement lighting.",
    "CALIFORNIA MODERN": "expansive luxury living, massive low-profile linen sectional sofa, organic modern elements, oversized abstract art on walls, large indoor olive trees to fill vertical space, seamless airy flow suitable for large open spaces.",

    "VITRA": "Vitra design icons.",
    "BOCONCEPT": "urban danish design.",
    "ROCHE BOBOIS": "french luxury, rich textures.",
    "MINOTTI": "italian ultra-luxe.",
    "KNOLL": "structured design, chrome steel tubes.",
    "HERMAN MILLER": "high-end ergonomic furniture.",
    "LIGNE ROSET": "french contemporary relaxed design, featuring iconic Togo sofas, soft plush forms, vibrant yet elegant colors.",
    "BULTHAUP": "german luxury kitchen minimalism.",
    "BOFFI": "italian ultra-luxe kitchen.",
    "POLIFORM": "italian ultra-luxe kitchen/closet.",
    "ARTHUR BONNET": "french elegance kitchen.",
    "PORCELANOSA": "spanish ultra-luxury bathroom, large-format textured ceramic tiles, minimalist high-end fixtures, spa-like elegant atmosphere."
};

const styleDescription = styleLibrary[chosenStyle] || chosenStyle;
const styleAnchor = ` [STYLE ADAPTATION REQUIRED]: You must adapt the style code '${chosenStyle}' (${styleDescription}) to specifically fit a '${roomEN}'.`;

let finalPrompt = "";

// >>> STRICT ARCHITECTURAL RULES (anti-hallucination guard) <<<
const baseRules = "[STRICT ARCHITECTURAL RULES - ZERO TOLERANCE]: This is an IN-PLACE PHOTO EDIT of the provided photograph, NOT a new render. 1. ABSOLUTELY PRESERVE the existing fixed architecture of the provided photo (walls, ceiling molding, windows, doors, floor, outlets). Do NOT change the technical structure. ABSOLUTELY NO new architectural elements added. 2. MAINTAIN EXACT CAMERA ANGLE and perspective. 3. RESPECT exact room proportions. 4. Natural direct daylight, professional photorealistic render. 5. FOREGROUND SAFETY: Keep immediate foreground open and clear. ";
const lightingRule = " LIGHTING: Respect existing electrical outlets. Dress exposed wires with a beautiful lamp adapted to the style. If no outlet, do NOT invent one. ";
// Appended at the VERY END of every generation prompt (image models weigh the
// end of the prompt heavily) — locks camera and room geometry.
const cameraLock = " [FINAL HARD CONSTRAINTS - VERIFY BEFORE OUTPUT]: This is an in-place edit of the input photograph. 1) Camera position, angle, framing, perspective and focal length must be PIXEL-IDENTICAL to the input photo - do not zoom out, do not widen the view, do not rotate. 2) Room geometry is FROZEN: same walls, same ceiling, same windows, same doors, same floor area - never extend or reproportion the room. 3) Do NOT add ceiling-mounted or architectural elements: no chandeliers, no ceiling lights, no fireplaces, no extra windows, no moldings. 4) Added furniture and decor must fit entirely WITHIN the space visible in the original photo. If a styling instruction conflicts with these constraints, the constraints win.";

// =========================================================================
// 6. ACTION LOGIC
if (chosenAction === "UPSCALE") {
    finalPrompt = "NO_PROMPT_REQUIRED_FOR_UPSCALE";

} else if (chosenAction === "EMPTY") {
    finalPrompt = baseRules + "REQUIRED ACTION: Remove absolutely ALL furniture, objects, and decorations to render this room entirely empty. Architecture only visible.";

} else if (chosenAction === "CLEAN") {
    finalPrompt = baseRules + "REQUIRED ACTION: Virtually clean this room. Remove clutter, trash, wires, and work marks. Make the space impeccable and airy. STRICT NEGATIVE PROMPT: DO NOT add any fireplaces, DO NOT add radiators, DO NOT add furniture, DO NOT add decorations. Only restore the bare walls and floor where items were removed.";

} else {
    // ACTION = FURNISH
    const furnishBase = baseRules + "6. LIFESTYLE: elegant lived-in aspect. ";
    let specificPrompt = "";

    if (roomEN === "STUDIO APARTMENT") {
        specificPrompt = `FUNCTION: STUDIO APARTMENT.${styleAnchor} WINDOWS: Curtains neatly arranged. [MULTI-FUNCTIONAL SPACE RULE]: Smartly organize this single room into a cohesive, fully-equipped studio apartment. FURNISHING: You MUST include three functional zones: 1. A sleeping area with a comfortable bed. 2. A compact, functional kitchenette along a wall. 3. A small multi-purpose dining/work table with chairs. Ensure harmonious flow between the living, sleeping, and cooking zones without overcrowding the space. ${lightingRule}`;
    } else if (roomEN === "LARGE LIVING ROOM") {
        specificPrompt = `FUNCTION: LARGE SCALE LIVING ROOM / LOFT.${styleAnchor} WINDOWS: Curtains neatly arranged, keeping the outside view clear. [GRAND VOLUME RULE]: Use oversized, large-scale furniture suited to the generous volume, placed ONLY within the area visible in the photo — never widen the view to show more space. Create up to 2 functional zones inside the visible area (e.g., main lounge + reading corner). Do not leave large empty gaps in the visible floor. Large area rugs to define zones. ${lightingRule}`;
    } else if (roomEN === "LIVING ROOM") {
        if (chosenStyle === "ECLECTIC CHIC") {
            specificPrompt = `FUNCTION: LIVING ROOM.${styleAnchor} WINDOWS: Curtains neatly arranged, keeping the outside view clear. [AVANT-GARDE GALLERY RULE]: The room must be ultra-minimalist, airy, and uncluttered. Give the AI creative freedom for a curated design icon gallery. FURNISHING: ONE statement round white Saarinen Tulip dining table with a pair of white Tulip-style chairs featuring vibrant color-blocking (specify color cushions). Add ONE iconic Mid-Century modern lounge chair (e.g., leather swivel chair). Add ONE giant Arco polished chrome floor lamp. DECORATION: Add LARGE scale contemporary art sculptures. LARGE floor space clear. ABSOLUTELY NO traditional small clutter. Airy modern gallery feel. Sun-drenched sunburst view. ${lightingRule}`;
        } else {
            specificPrompt = `FUNCTION: LIVING ROOM.${styleAnchor} WINDOWS: Curtains neatly arranged, keeping the outside view clear. FURNISHING AND DECORATION: The layout (sofa, coffee table, rug, dining zone, etc.) must STRICTLY follow the requested style directives above.${lightingRule}`;
        }
    } else if (roomEN === "KITCHEN") {
        specificPrompt = `FUNCTION: FITTED KITCHEN.${styleAnchor} FURNISHING: Built-in oven, refrigerator. LIGHTING: LED strips.${lightingRule}`;
    } else if (roomEN === "BEDROOM") {
        specificPrompt = `FUNCTION: BEDROOM.${styleAnchor} WINDOWS: Curtains neatly arranged. FURNISHING: Generous double bed, nightstands. DECORATION: Throw blanket, book, wall art.${lightingRule}`;
    } else if (roomEN === "KIDS ROOM") {
        specificPrompt = `FUNCTION: KIDS ROOM.${styleAnchor} WINDOWS: Curtains neatly arranged. FURNISHING: Kids bed, small desk. DECORATION: Play rug, wooden toys. Soft and bright.${lightingRule}`;
    } else if (roomEN === "BALCONY") {
        specificPrompt = `FUNCTION: BALCONY.${styleAnchor} FURNISHING: Minimal outdoor seating. Plants.`;
    } else if (roomEN === "OFFICE") {
        specificPrompt = `FUNCTION: HOME OFFICE.${styleAnchor} WINDOWS: Curtains neatly arranged. FURNISHING: Desk, ergonomic chair. DECORATION: Rug, book, mug.${lightingRule}`;
    } else if (roomEN === "BATHROOM") {
        specificPrompt = `FUNCTION: BATHROOM.${styleAnchor} FURNISHING: Keep existing fixtures. Add elegant bath linen.${lightingRule}`;
    } else {
        specificPrompt = `FUNCTION: ${roomEN}.${styleAnchor} FURNISHING: Perfectly fitted, uncluttered furniture. Minimal lived-in feel.${lightingRule}`;
    }

    finalPrompt = furnishBase + specificPrompt;
}

// =========================================================================
// === User comment ===
const userComment = (items[0].json.comment || "").trim();
if (userComment) {
  finalPrompt = finalPrompt + " ADDITIONAL USER INSTRUCTIONS: " + userComment + ".";
}

// Camera/geometry lock goes LAST so it outweighs everything above —
// including style directives and user instructions.
if (chosenAction !== "UPSCALE") {
  finalPrompt = finalPrompt + cameraLock;
}

// 7. ASSEMBLE AND SEND
return {
  json: {
    ...items[0].json,
    finalPrompt: finalPrompt,
    roomType: roomEN,
    action: actionEN,
    // Only meaningful for FURNISH — kept empty otherwise so the job log
    // and the stats page never count a style that was not actually used.
    styleDetected: actionEN === "FURNISH" ? chosenStyle : ""
  },
  binary: {
    data: items[0].binary.photo
  }
};

if (!items[0].binary) {
  throw new Error("No binary data (image) reached this node.");
}
const binaryKeyName = Object.keys(items[0].binary)[0];
if (!binaryKeyName) {
  throw new Error("The binary folder is empty!");
}
const binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKeyName);
const mimeType = items[0].binary[binaryKeyName].mimeType;
const base64Data = binaryDataBuffer.toString('base64');
const imageUrl = `data:${mimeType};base64,${base64Data}`;
return {
  json: {
    ...items[0].json,
    fal_image_url: imageUrl
  }
};

// The data-table insert above replaces the item with the DB row and drops
// the photo. Re-emit Brain's full output (prompt + binary) so generation runs.
return [{ json: $('Brain').first().json, binary: $('Brain').first().binary }];

const row = items.length ? items[0].json : null;
if (!row || !row.jobId) {
  return [{ json: { status: 'pending' } }];
}
// Never leak the raw provider error to the public client — the form shows a
// generic localized message. The detail stays in the data table for the owner.
return [{ json: { status: row.status } }];

// ====== STATS SETTINGS (edit here) ======
const ACCESS_PIN = "";        // protect this page — use the same code as in Access gate AND "Save settings" ("" = public, read-only quota)
const COST_PER_IMAGE = 0.13;  // your estimated API cost per generation
const CURRENCY = "€";
const LANGUAGE = "en";        // "en" | "fr" | "de"
const DEFAULT_DAILY_LIMIT = 30; // shown until you change it below; should match DAILY_LIMIT in the Access gate node
// ========================================

const T = {
  en: { title: "Usage & costs", sub: "Pay only for what you generate.", today: "Today", month: "This month", all: "All time", est: "≈ {c} estimated", last14: "Last 14 days", byAction: "By action", topStyles: "Top styles", errors: "failed generations", note: "Estimated at {p} per image — edit COST_PER_IMAGE in the “Stats page” node.", denied: "Access denied — append ?pin=YOUR_CODE to the URL.", empty: "No generations yet.", limitTitle: "Daily generation limit", used: "used today", unlimited: "Unlimited", save: "Save", saved: "Saved", saveErr: "Save failed", limitHint: "0 = unlimited. Protects your API budget.", actions: { FURNISH: "Furnish", EMPTY: "Empty", CLEAN: "Clean", UPSCALE: "Upscale" } },
