const rows = items.map(i => i.json).filter(r => r && r.jobId);
const dToday = $now.toFormat("yyyy-MM-dd");
const dMonth = dToday.slice(0, 7);
let nToday = 0, nMonth = 0, nErr = 0;
const byAction = {}, byStyle = {}, byDay = {};
for (const r of rows) {
  const day = r.day || "";
  if (day === dToday) nToday++;
  if (day.indexOf(dMonth) === 0) nMonth++;
  if (r.status === "error") nErr++;
  const a = r.action || "?";
  byAction[a] = (byAction[a] || 0) + 1;
  if (r.status !== "error" && a === "FURNISH" && r.style) byStyle[r.style] = (byStyle[r.style] || 0) + 1;
  if (day) byDay[day] = (byDay[day] || 0) + 1;
}

let bars = "", maxBar = 1;
const days = [];
for (let i = 13; i >= 0; i--) {
  const d = $now.minus({ days: i }).toFormat("yyyy-MM-dd");
  const v = byDay[d] || 0;
  days.push([d, v]);
  if (v > maxBar) maxBar = v;
}
for (const dv of days) {
  const h = Math.max(3, Math.round((dv[1] / maxBar) * 76));
  bars += '<div class="bcol" title="' + dv[0] + " · " + dv[1] + '"><div class="bar" style="height:' + h + "px;opacity:" + (dv[1] ? 1 : 0.25) + '"></div></div>';
}

