// ====== must match the ACCESS_PIN of the "Stats page" node ======
const SETTINGS_PIN = "";
// ================================================================

const body = items[0].json.body || items[0].json;
const pin = (body.pin || "").toString();
if (!SETTINGS_PIN || pin !== SETTINGS_PIN) {
  return [{ json: { ok: false, error: "denied" } }];
}
let n = parseInt(body.daily_limit, 10);
// Un champ vide ou non numerique ne doit JAMAIS devenir 0 (= illimite) :
// cela supprimerait le plafond de depense en affichant "Saved".
if (isNaN(n) || n < 0) {
  return [{ json: { ok: false, error: "invalid" } }];
}
if (n > 100000) n = 100000;
const sd = $getWorkflowStaticData("global");
sd.dailyLimit = n;
return [{ json: { ok: true, daily_limit: n } }];
